#include "NFLookAndFeel.h"
NFLookAndFeel::NFLookAndFeel(){setColour(juce::Slider::textBoxTextColourId,juce::Colours::white);setColour(juce::Slider::textBoxBackgroundColourId,juce::Colour(0xff10151b));setColour(juce::Slider::textBoxOutlineColourId,juce::Colours::transparentBlack);}
void NFLookAndFeel::drawRotarySlider(juce::Graphics& g,int x,int y,int w,int h,float pos,float a0,float a1,juce::Slider&){auto r=juce::Rectangle<float>(x,y,w,h).reduced(8);float rad=juce::jmin(r.getWidth(),r.getHeight())*.5f,ang=a0+pos*(a1-a0);auto c=r.getCentre();g.setColour(juce::Colour(0xff07090c));g.fillEllipse(r);g.setColour(juce::Colour(0xff343b44));g.drawEllipse(r,2);juce::Path arc;arc.addCentredArc(c.x,c.y,rad-4,rad-4,0,a0,ang,true);g.setColour(juce::Colour(0xff9560e7));g.strokePath(arc,juce::PathStrokeType(5,juce::PathStrokeType::curved,juce::PathStrokeType::rounded));juce::Path p;p.addRoundedRectangle(-1.5f,-rad*.68f,3,rad*.42f,1.5f);p.applyTransform(juce::AffineTransform::rotation(ang).translated(c.x,c.y));g.setColour(juce::Colours::white);g.fillPath(p);}
void NFLookAndFeel::drawButtonBackground(juce::Graphics& g,juce::Button& b,const juce::Colour&,bool over,bool down){auto r=b.getLocalBounds().toFloat().reduced(1);g.setColour(down?juce::Colour(0xff7e50ca):(over?juce::Colour(0xff2b2535):juce::Colour(0xff171c22)));g.fillRoundedRectangle(r,5);g.setColour(juce::Colour(0xff3c4650));g.drawRoundedRectangle(r,5,1);}
